using System.Windows;using System.Windows.Controls;using OdinVault.Manager.Wpf.Services;namespace OdinVault.Manager.Wpf.Views;public partial class SettingsView:System.Windows.Controls.UserControl{readonly ManagerSettingsStore store;readonly Action<ManagerSettings> applied;ManagerSettings settings;internal SettingsView(ManagerSettingsStore store,ManagerSettings settings,Action<ManagerSettings> applied){InitializeComponent();this.store=store;this.settings=settings;this.applied=applied;StartMinimized.IsChecked=settings.StartMinimizedToTray;MinimizeToTray.IsChecked=settings.MinimizeToTray;Notifications.IsChecked=settings.ShowTrayNotifications;AutoUpdate.IsChecked=settings.CheckForUpdatesOnStart;Theme.SelectedValue=settings.Theme;LanguageCombo.SelectedValue=settings.Language;}void Save_Click(object s,RoutedEventArgs e){settings=settings with{StartMinimizedToTray=StartMinimized.IsChecked==true,MinimizeToTray=MinimizeToTray.IsChecked==true,ShowTrayNotifications=Notifications.IsChecked==true,CheckForUpdatesOnStart=AutoUpdate.IsChecked==true,Theme=Theme.SelectedValue?.ToString()??"Light",Language=LanguageCombo.SelectedValue?.ToString()??"fa"};store.Save(settings);applied(settings);Status.Text="تنظیمات ذخیره شد.";}}